-- Minimal Hyprland config created by arch-lxc-sunshine (container/01-system.sh).
-- It is only created when missing: edit it freely, re-running ./install.sh keeps it.
-- The monitor rule lives in monitors.lua, regenerated by container/03-session.sh.
-- Reference: https://wiki.hypr.land/Configuring/Start/

local kb_layout = "@KB_LAYOUT@"

-- Output name and mode (1920x1080@60 on the HDMI dummy plug), written by 03-session.sh.
pcall(dofile, (os.getenv("HOME") or "") .. "/.config/hypr/monitors.lua")

local input = { follow_mouse = 1 }
if kb_layout ~= "" then
  input.kb_layout = kb_layout
end

hl.config({
  input = input,
  general = {
    gaps_in = 5,
    gaps_out = 10,
    border_size = 2,
    layout = "dwindle",
  },
  misc = {
    disable_hyprland_logo = true,
    disable_splash_rendering = true,
    force_default_wallpaper = 0,
  },
})

hl.on("hyprland.start", function()
  -- Export the session environment (WAYLAND_DISPLAY, HYPRLAND_INSTANCE_SIGNATURE...) to the
  -- systemd user manager, then start the target that brings up Sunshine.
  hl.exec_cmd("dbus-update-activation-environment --systemd --all && systemctl --user start hyprland-session.target")
  hl.exec_cmd("systemctl --user start hyprpolkitagent.service || true")
end)

hl.bind("SUPER + RETURN", hl.dsp.exec_cmd("foot"))
hl.bind("SUPER + SPACE", hl.dsp.exec_cmd("fuzzel"))
hl.bind("SUPER + Q", hl.dsp.window.close())
hl.bind("SUPER + T", hl.dsp.window.float({ action = "toggle" }))
hl.bind("SUPER + F", hl.dsp.window.fullscreen({ mode = "fullscreen" }))

hl.bind("SUPER + LEFT", hl.dsp.focus({ direction = "l" }))
hl.bind("SUPER + RIGHT", hl.dsp.focus({ direction = "r" }))
hl.bind("SUPER + UP", hl.dsp.focus({ direction = "u" }))
hl.bind("SUPER + DOWN", hl.dsp.focus({ direction = "d" }))

for i = 1, 5 do
  hl.bind("SUPER + " .. i, hl.dsp.focus({ workspace = tostring(i) }))
  hl.bind("SUPER + SHIFT + " .. i, hl.dsp.window.move({ workspace = tostring(i) }))
end
